package com.dataengine.governance.service;
import com.dataengine.governance.domain.*; import com.dataengine.governance.repository.GovernanceNotificationRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class NotificationService {private final GovernanceNotificationRepository notifications;public NotificationService(GovernanceNotificationRepository n){notifications=n;}public void notify(String recipient,String category,String title,String content,UUID changeId){notifications.save(new GovernanceNotification(recipient,category,title,content,changeId));}@Transactional(readOnly=true)public List<GovernanceNotification> inbox(String recipient){return notifications.findByRecipientOrderByCreatedAtDesc(recipient);}@Transactional(readOnly=true)public long unread(String recipient){return inbox(recipient).stream().filter(n->n.getStatus()==NotificationStatus.UNREAD).count();}public GovernanceNotification markRead(UUID id){GovernanceNotification n=notifications.findById(id).orElseThrow(()->new GovernanceException("通知不存在"));n.markRead();return n;}}
